facilityFormItem.valueChangedEventHandler:
        ESS.toasts.hideToast(window.partTimeEmployeesInfo);
        functions.removeError(window.errorCurrentVacation);
        functions.setValue('EmployeePosition', null);
        functions.setValue('CurrentVacation', ' ');
        functions.setValue('BeginDateCurrent', null);
        functions.setValue('EndDateCurrent', null);
        functions.setValue('DurationCurrent', null);
        if (functions.getValues().BeginDateRecall)
          functions.setValue('BeginDateRecall', null);
        if (functions.getValues().EndDateRecall)
          functions.setValue('EndDateRecall', null);

        var employeeId = formItem.value;
        if (!employeeId)
          return;
        ESS.network.sendRequest(`/api/functions/NNGetSubstitutePositionAndJobTitle?employeeId=${employeeId}`)
        .then(function (employeePosition) {
          functions.setValue('EmployeePosition', employeePosition);
        });

        ESS.network.sendRequest(`/api/functions/GetCurrentVacationForRecall?employeeId=${employeeId}`)
        .then(function (vacationData){
          if (!vacationData.ErrorText || vacationData.ErrorText.length == 0) {
            functions.setValue('CurrentVacationData', JSON.stringify(vacationData.CurrentVacations));
            functions.setValue('CurrentVacation', vacationData.VacationPeriod);
            functions.setValue('BeginDateCurrent', vacationData.CurrentDateStart);
            functions.setValue('EndDateCurrent', vacationData.CurrentDateEnd);
            functions.setValue('DurationCurrent', vacationData.DayCount);

            ESS.network.sendRequest(`/api/functions/GetPartTimeEmployeesInfo?employeeId=${employeeId}`)
            .then(function (info) {
              if (info) {
                info = ESS.L('@HRPROVACATIONS.FACILITIES_NNRECALLVACATIONEMPLOYEE_PARTTIMEEMPLOYEES_WARNING') + '\r\n' + info;
                window.partTimeEmployeesInfo = ESS.toasts.showToast(info, 'warning', false);
              }
            });
          }
          else {
            window.errorCurrentVacation = functions.showError(vacationData.ErrorText, undefined, ESS.enums.FormErrorType.UNSPECIFIED);
          }
        });

functions.removeError(window.errorBeginDateRecall);
